shader_type canvas_item;
uniform float warn_amount : hint_range(0.0, 1.0) = 0.0;
uniform vec3 warn_color: source_color = vec3(0.839216, 0.235294, 0.184314);

void fragment(){
COLOR.rgb = mix(COLOR.rgb, warn_color, warn_amount);
}

shader_type spatial;
render_mode unshaded;

uniform sampler2D bands_srgb : source_color, filter_nearest;
uniform sampler2D bands_data : filter_nearest;

uniform bool use_source_color = true;

void fragment() {
	// 遮罩：0 表示干燥，1 表示完全湿润。
	float w = texture(wetness_mask, UV).r;

	// 石头本色乘上颜色调整。
	vec3 base = texture(stone_albedo, UV).rgb * tint;

	// 越湿越暗。
	ALBEDO = base * (1.0 - w * water_darkening);

	// 根据湿度，在干燥和湿润粗糙度之间插值。
	ROUGHNESS = mix(roughness_dry, water_roughness, w);
}

shader_type spatial;
render_mode blend_mix, depth_draw_opaque, cull_back, diffuse_burley, specular_schlick_ggx;

uniform vec4 albedo : source_color;
uniform sampler2D texture_albedo : source_color, filter_linear_mipmap, repeat_enable;
uniform ivec2 albedo_texture_size;
uniform float point_size : hint_range(0.1, 128.0, 0.1);

uniform float roughness : hint_range(0.0, 1.0);
uniform sampler2D texture_metallic : hint_default_white, filter_linear_mipmap, repeat_enable;
